CREATE OR REPLACE FUNCTION public.guard_lead_operations() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF current_setting('app.lead_operations',true)='allowed' THEN RETURN NEW; END IF; IF TG_OP='INSERT' THEN IF NEW.requirement_id IS NOT NULL OR NEW.assignee IS NOT NULL OR NEW.response_due_at IS NOT NULL OR NEW.first_response_at IS NOT NULL OR NEW.quotation_sent_at IS NOT NULL OR NEW.quotation_text<>'' OR NEW.outcome_reason<>'' THEN RAISE EXCEPTION 'Operational fields require a validated workflow'; END IF; ELSE IF NEW.business_id IS DISTINCT FROM OLD.business_id OR NEW.requirement_id IS DISTINCT FROM OLD.requirement_id OR NEW.assignee IS DISTINCT FROM OLD.assignee OR NEW.response_due_at IS DISTINCT FROM OLD.response_due_at OR NEW.first_response_at IS DISTINCT FROM OLD.first_response_at OR NEW.quotation_sent_at IS DISTINCT FROM OLD.quotation_sent_at OR NEW.quotation_text IS DISTINCT FROM OLD.quotation_text OR NEW.outcome_reason IS DISTINCT FROM OLD.outcome_reason THEN RAISE EXCEPTION 'Operational fields require a validated workflow'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER guard_lead_operations BEFORE INSERT OR UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.guard_lead_operations();
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='assign_requirement'; def:=replace(def,'BEGIN SELECT','BEGIN PERFORM set_config(''app.lead_operations'',''allowed'',true); SELECT'); def:=replace(def,'r.topic||'': ''||r.description','left(r.topic||'': ''||r.description,1000)'); def:=replace(def,'RETURN lid;','PERFORM set_config(''app.lead_operations'','''',true); RETURN lid;'); EXECUTE def;
SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='lead_operations_action'; def:=replace(def,'BEGIN SELECT','BEGIN PERFORM set_config(''app.lead_operations'',''allowed'',true); SELECT'); def:=replace(def,'END; $function$','PERFORM set_config(''app.lead_operations'','''',true); END; $function$'); EXECUTE def; END $$;
CREATE OR REPLACE FUNCTION public.guard_requirement_links() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.lead_id IS NOT NULL AND NEW.business_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.leads WHERE id=NEW.lead_id AND business_id=NEW.business_id) THEN RAISE EXCEPTION 'Lead does not belong to linked business'; END IF; IF NEW.claim_id IS NOT NULL AND NEW.business_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.business_claims WHERE id=NEW.claim_id AND business_id=NEW.business_id) THEN RAISE EXCEPTION 'Claim does not belong to linked business'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER support_link_guard BEFORE INSERT ON public.support_tickets FOR EACH ROW EXECUTE FUNCTION public.guard_requirement_links();